<script setup lang="ts">import { ref } from "vue";import {ElMessage,ElMessageBox} from "element-plus";import {createApiClient} from "../../api/platform";const key=ref("");const secret=ref("");async function create(){try{const r=await createApiClient({client_key:key.value,scopes:["crm:read"]});secret.value=r.data?.data?.secret??"";ElMessage.success("客户端已创建")}catch{ElMessage.error("客户端创建失败")}}async function disable(){try{await ElMessageBox.confirm("确认停用客户端？","确认")}catch{return}}</script>
<template><el-card><template #header>OpenAPI 客户端</template><el-input v-model="key" placeholder="客户端 Key"/><el-button @click="create">创建</el-button><el-alert v-if="secret" :title="`Secret：${secret}`" type="success"/></el-card></template>
